import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

import Intro from "./components/Intro";
import Register from "./components/Register";
import Login from "./components/Login";
import Dashboard from "./components/Dashboard";
import ViewSendMessages from "./components/ViewSendMessages";

function App() {
  return (
    <Router>
      <Routes>
        {/* Home screen (Intro) */}
        <Route path="/" element={<Intro />} />

        {/* Register screen */}
        <Route path="/register" element={<Register />} />

        {/* Login screen */}
        <Route path="/login" element={<Login />} />

        {/* Main dashboard showing unique senders */}
        <Route path="/dashboard" element={<Dashboard />} />

        {/* View and send messages with a specific user */}
        <Route path="/messages/:userId" element={<ViewSendMessages />} />

        {/* Catch-all fallback */}
        <Route path="*" element={<div style={{ padding: "2rem", textAlign: "center" }}><h2>404 - Page Not Found</h2></div>} />
      </Routes>
    </Router>
  );
}

export default App;
